begin;
update public.app_translation_keys set default_text='Saved to your account and available offline on this device. Tap the heart on a service to save it.' where key='customer.saved_on_this_device_for_your_account_tap_the.30fe77e0';
update public.app_translation_keys set default_text='Your submitted reviews appear here. Give a new review from a completed booking in Bookings.' where key='customer.your_reviews_and_services_ready_for_review_wi.13f80382';
update public.app_languages set draft_revision=draft_revision+1 where code in('en','ta');
do $$ declare lang record; messages jsonb; payload text; version integer; missing integer;
begin
 for lang in select * from public.app_languages where code in ('en','ta') and is_enabled for update loop
  select jsonb_object_agg(k.key,case when lang.code='en' or length(trim(coalesce(d.value,'')))=0 then k.default_text else d.value end),
   count(*) filter(where lang.code<>'en' and length(trim(coalesce(d.value,'')))=0)
  into messages,missing from public.app_translation_keys k left join public.app_translation_drafts d on d.key=k.key and d.language_code=lang.code where k.is_active;
  version:=lang.published_version+1;
  payload:=jsonb_build_object('schema',1,'app','vendor','code',lang.code,'version',version,'direction',lang.direction,'messages',messages)::text;
  update public.app_languages set published_version=version,updated_at=clock_timestamp() where code=lang.code;
 end loop;
end $$;
select count(*) missing_customer_tamil from public.app_translation_keys k left join public.app_translation_drafts d on d.key=k.key and d.language_code='ta' where k.key like 'customer.%' and length(trim(coalesce(d.value,'')))=0;
commit;
